return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Multilingual WordPress, isang post sa bawat wika: mga naka-link na pagsasalin ng mga post, pahina, kategorya, media text, widget, at pamagat ng site, kasama ang iyong mga lumang Tranzly na pagsasalin na na-import.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Mga AI provider','The makers of ChatGPT. A good all-rounder.'=>'Ang mga tagalikha ng ChatGPT. Isang mahusay na panglahat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Ang mga lumikha ng Claude. Mahusay sa pagsulat at maingat na pangangatwiran.','Google\'s Gemini models. Fast and inexpensive.'=>'Mga modelo ng Gemini ng Google. Mabilis at mura.','A European AI company with fast, inexpensive models.'=>'Isang European AI company na may mabilis at murang mga modelo.','Low-cost models that are good at writing and code.'=>'Mga murang modelo na magaling sa pagsusulat at pagsusulat ng code.','One key for models from many different providers.'=>'Isang susi para sa mga modelo mula sa maraming iba\'t ibang provider.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Anumang serbisyo na gumagana tulad ng API ng OpenAI, kabilang ang isang modelong tumatakbo sa sarili mong computer o server.','General (used when nothing more specific is set)'=>'Pangkalahatan (ginagamit kapag walang mas tiyak na nakatakda)','Writing and rewriting'=>'Pagsusulat at muling pagsusulat','Translation'=>'Pagsasalin','Code and CSS'=>'Code at CSS','Sorry, you are not allowed to access this page.'=>'Pasensya na, hindi ka pinahihintulutang ma-access ang pahinang ito.','These settings are shared by every plugin that uses them: %s.'=>'Ang mga setting na ito ay ibinabahagi ng bawat plugin na gumagamit sa kanila: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Naka-encrypt ang iyong mga susi sa database ng site na ito at ipinapadala lamang sa provider na iyong pinili — hindi kailanman sa amin.','Step 1 of 2: choose an AI provider'=>'Hakbang 1 sa 2: pumili ng provider ng AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Nagdadala ka ng sarili mong key, kaya direktang binabayaran mo ang provider para sa iyong ginagamit. Hindi sigurado? Aluman sa mga ito ay maayos; maaari kang magdagdag ng iba mamaya.','Next'=>'Susunod','Step 2 of 2: connect %s'=>'Hakbang 2 ng 2: ikonekta ang %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Ilagay ang address ng iyong serbisyong tugma sa OpenAI, na nagtatapos sa /v1. Kinakailangan lamang ang isang susi kung humihingi nito ang serbisyo.','Open %s and sign in (or create a free account).'=>'Buksan ang %s at mag-sign in (o gumawa ng libreng account).','the %s API keys page'=>'ang pahina ng %s API keys','Create a new key and copy it.'=>'Gumawa ng bagong susi at kopyahin ito.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'I-paste ito sa ibaba at pindutin ang "Save and test". Nagpapadala kami ng isang maliit na kahilingan upang suriin kung gumagana ito.','Most providers need a little credit on the account before a key works: %s.'=>'Kailangan ng karamihan sa mga provider ng kaunting credit sa account bago gumana ang key: %s.','add credit'=>'magdagdag ng credit','← Choose a different provider'=>'← Pumili ng ibang provider','Address'=>'Address','Saved key ends in …%s — paste a new one to replace it'=>'Nagtatapos ang naka-save na key sa …%s — mag-paste ng bago para mapalitan ito','Key (optional)'=>'Susi (opsyonal)','API key'=>'API key','Save and test'=>'I-save at subukan','Providers'=>'Mga Provider','Provider'=>'Tagapagbigay','Status'=>'Katayuan','Key'=>'Susi','Get a key'=>'Kumuha ng susi','Test'=>'Subukin','Remove'=>'Alisin','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Na-save sa mas bagong bersyon ng plugin: i-update ang plugin na ito, o ilagay muli ang key.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Hindi na mabubuksan ang nakapirming susi (nagbago ang mga susi sa seguridad ng site). Ipasok itong muli.','Not connected'=>'Hindi nakakonekta','Connected — last test passed %s'=>'Nakakonekta — matagumpay ang huling pagsubok %s','Last test failed: %s'=>'Nabigo ang huling pagsubok: %s','Connected — not tested yet'=>'Konektado — hindi pa nasusubukan','Which model to use'=>'Aling modelo ang gagamitin','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ang nagmamarka sa aming rekomendasyon para sa gawaing iyon. Kasama sa listahan ang bawat modelong magagamit ng iyong key, na direktang binabasa mula sa provider.','— Recommended for the provider —'=>'— Inirerekomenda para sa provider —','Save models'=>'I-save ang mga modelo','Refresh the model lists from the providers'=>'I-refresh ang mga listahan ng modelo mula sa mga provider','best quality'=>'pinakamataas na kalidad','lowest cost'=>'pinakamababang gastos','fastest'=>'pinakamabilis','Add a model yourself'=>'Magdagdag ng modelo nang mag-isa','A model came out today? Paste its exact name to use it straight away.'=>'May lumabas na modelo ngayon? I-paste ang eksaktong pangalan nito para magamit agad.','Model name'=>'Pangalan ng modelo','Add model'=>'Magdagdag ng modelo','Recommended models list'=>'Listahan ng mga inirerekomendang modelo','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Hindi ma-verify ang listahan ng mga inirerekomendang modelo, kaya walang ipinapakitang mga rekomendasyon. I-install muli ang plugin, o i-on ang mga pang-araw-araw na update sa ibaba.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Nai-publish ang listahang ginagamit noong %s. Nagdadala ang bawat pag-update ng plugin ng bago.','Also check Zinn Digital® once a day for an updated list.'=>'Suriin din ang Zinn Digital® minsan sa isang araw para sa na-update na listahan.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Isang simpleng kahilingan sa pag-download lamang ang ipinapadala: walang susing ibinigay, walang address ng site, walang anumang tungkol sa iyong nilagyan ng nilalaman. Ang listahan ay nilagdaan, at ang listahang nabigo sa pagsusuri ng lagda ay binabalewala.','Last checked %1$s: %2$s.'=>'Huling sinuri noong %1$s: %2$s.','Save, and check now if turned on'=>'I-save, at suriin ngayon kung naka-on','a newer list was installed'=>'na-install ang isang mas bagong listahan','already up to date'=>'nasa pinakabagong bersyon na','the download failed the signature check and was ignored'=>'nabigo ang pag-download sa pagsusuri ng lagda at hindi pinansin','Zinn Digital® could not be reached; the current list stays in use'=>'Hindi maabot ang Zinn Digital®; nananatiling ginagamit ang kasalukuyang listahan','turned off'=>'naka-off','Open'=>'Buksan','Check their status page'=>'Suriin ang kanilang pahina ng katayuan','Open your billing page'=>'Buksan ang iyong pahina ng pagsingil','Open your API keys page'=>'Buksan ang iyong pahina ng mga API key','Open the AI settings'=>'Buksan ang mga setting ng AI','Sorry, you are not allowed to do that.'=>'Paumanhin, hindi ka pinahihintulutang gawin iyon.','Unknown provider.'=>'Hindi kilalang provider.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Ipasok ang address ng iyong serbisyo, halimbawa ay http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Hindi iyon mukhang API key. Kopyahin itong muli, nang walang mga espasyo.','Paste your API key first.'=>'I-paste muna ang iyong API key.','Key removed.'=>'Naalis na ang susi.','Models saved.'=>'Nai-save na ang mga modelo.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Ilagay ang eksaktong pangalan ng modelo, halimbawa kung paano ito nakasaad sa dokumentasyon ng provider.','Added %s. Choose it under "Which model to use".'=>'Idinagdag ang %s. Piliin ito sa ilalim ng "Aling modelo ang gagamitin".','Model removed.'=>'Inalis ang modelo.','Daily updates are off. The list that came with the plugin is used.'=>'Naka-off ang mga pang-araw-araw na pag-update. Ginagamit ang listahang kasama ng plugin.','Checked: %s.'=>'Nasuri: %s.','Model lists refreshed.'=>'Na-refresh na ang mga listahan ng modelo.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Na-save ang iyong AI key ng mas bagong bersyon ng isa sa iyong mga plugin. I-update ang plugin na ito, o ilagay muli ang key sa mga setting ng AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Hindi na buksan ang iyong nakaimbak na AI key (nagbago ang mga security key ng site). Ilagay itong muli sa mga setting ng AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Hindi pa naka-set up ang AI. Magdagdag ng key para sa AI provider sa mga setting ng AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Walang napiling modelo para sa gawaing ito. Pumili ng isa sa mga setting ng AI.','That AI provider is not supported by this version of the plugin.'=>'Ang AI provider na iyon ay hindi sinusuportahan ng bersyong ito ng plugin.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Hindi maabot ng site na ito ang iyong serbisyo ng AI. Suriin kung ito ay tumatakbo at kung ang address nito ay naaabot mula sa iyong web server (ang isang serbisyo sa iyong sariling computer ay hindi naaabot mula sa isang naka-host na site).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Hindi maabot ng site na ito ang %s. Suriin ang kanilang status page; kung gumagana sila, maaaring hinahararang ng iyong host ang mga papalabas na koneksyon, o mali ang address.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'Sabi ng %s na ang iyong account ay wala nang credit o quota. Magdagdag ng credit o itaas ang iyong limitasyon sa kanilang account, pagkatapos ay subukang muli.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'Hindi tinanggap ng %s ang iyong key. Maaaring mali ang pag-type nito, na-revoke, o nag-expire na. Gumawa ng bagong key at i-paste ito rito.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s tinanggihan ang kahilingang ito para sa iyong key. Maaaring walang access ang key sa model o feature na ito, o kailangang i-verify ang iyong account.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Hindi available ang model na "%1$s" mula sa %2$s para sa iyong key. Pumili ng ibang modelo sa mga setting ng AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Ang iyong planong %2$s ay hindi kasama ang modelong "%1$s". Pumili ng ibang modelo sa mga setting ng AI, o i-upgrade ang iyong plano sa kanila.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'Nililimitahan ng %s kung gaano kaqabilis makapagpadala ng mga kahilingan ang iyong key. Maghintay ng isang minuto at subukang muli, o pataasin ang iyong rate limit sa kanila.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'May mga problema ang %s sa ngayon (isang outage o overload sa kanilang bahagi). Walang mali sa iyong mga setting. Subukan itong muli mamaya-maya.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Nabigo ang kahilingan ng AI sa dahilang hindi namin matukoy. Subukang muli; kung magpatuloy ito, makipag-ugnayan sa suporta kasama ang mga detalye sa ibaba.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Sumagot ang AI provider sa anyong hindi mabasa ng plugin na ito. Subukan muli; kung magpatuloy ito, pumuli ng ibang modelo o makipag-ugnayan sa suporta.','Custom (OpenAI-compatible)'=>'Pasadya (tugma sa OpenAI)','Save a key for this provider first.'=>'Mag-save muna ng key para sa provider na ito.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Gumagana ang iyong key, ngunit walang nakalistang text model para rito ang provider. Magdagdag ng modelo sa ibaba.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Konektado. Sinagot ni %1$s gamit ang %2$s. Handang gamitin ang iyong mga AI feature.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Hindi pinahihintulutan ang iyong uri ng user na gumamit ng AI sa site na ito. Magtanong sa isang administrator.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon sa paggastos para sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon nito para sa mga kahilingan sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','Usage and cost'=>'Paggamit at gastusin','The log, limits and role permissions apply to AI used through: %s.'=>'Nalalapat ang log, mga limitasyon, and mga pahintulot sa papel sa AI na ginamit sa pamamagitan ng: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Ang mga gastusin ay humigit-kumulang, na kinuha mula sa mga nai-publish na presyo; ang isang modelo na walang kilalang presyo ay binibilang bilang zero.','This month: %1$s requests, about %2$s.'=>'Ngayong buwan: %1$s na kahilingan, humigit-kumulang %2$s.','When'=>'Kailan','Who'=>'Sino','Used for'=>'Ginagamit para sa','Model'=>'Modelo','Tokens in / out'=>'Mga Token na pumasok / lumabas','About'=>'Tungkol sa','Result'=>'Resultado','No AI requests have been made yet.'=>'Wala pang isinagawang kahilingan sa AI.','Done'=>'Tapos na','Limits and permissions'=>'Mga limitasyon at pahintulot','Monthly spending limit (US dollars)'=>'Buwanang limitasyon sa paggastos (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Iwanang bakasyon para sa walang hanggan. Humihinto ang AI para sa natitirang bahagi ng buwan kapag umabot dito ang tinatayang halaga.','Monthly request limit'=>'Buwanang limitasyon sa kahilingan','Leave empty for no limit.'=>'Hayaang blangko para sa walang limitasyon.','Who may use AI'=>'Sino ang maaaring gumamit ng AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Huwag lagyan ng tsek ang anuman upang payagan ang lahat ng maaaring gumamit ng mga feature ng plugin na gumamit ng AI. Palaging magagamit ito ng mga Administrator.','Save limits and permissions'=>'I-save ang mga limitasyon at pahintulot','Limits and permissions saved.'=>'Nai-save na ang mga limitasyon at pahintulot.','That language is not one of this site\'s languages.'=>'Ang wikang iyon ay hindi isa sa mga wika ng site na ito.','A translation must be the same kind of content as the original.'=>'Ang pagsasalin ay dapat na parehong uri ng nilalaman ng orihinal.','Choose one of the site\'s other languages.'=>'Pumili ng isa sa iba pang mga wika ng site.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Nawawala ang mga script ng screen ng admin mula sa kopya ng plugin na ito. I-install itong muli mula sa inilabas na package.','This screen needs JavaScript.'=>'Kailangan ng screen na ito ang JavaScript.','Choose a language'=>'Pumili ng wika','Upgrade'=>'Mag-upgrade','Pricing'=>'Pagpepresyo','Start Trial'=>'Simulan ang Pagsubok','Account'=>'Account','Contact Us'=>'Makipag-ugnayan sa Amin','Affiliation'=>'Kaugnayan','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Kumusta %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Mag-opt in upang makatanggap ng mga notification sa email para sa mga update sa seguridad at feature, nilalamang pang-edukasyon, at mga paminsan-minsang alok, at upang magbahagi ng ilang pangunahing impormasyon sa kapaligiran ng WordPress. Makakatulong ito sa amin na gawing mas tugma ang %s sa iyong site at mas mahusay sa paggawa ng kung ano ang kailangan mo rito.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Mag-opt in upang makatanggap ng mga notifikasyon sa email para sa mga update sa seguridad at feature, edukasyonal na nilalaman, at mga paminsan-minsang alok, at upang magbahagi ng ilang pangunahing impormasyon sa kapaligiran ng WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Kung lalaktawan mo ito, ayos lang! Gagana pa rin nang maayos ang %1$s.','Allow & Continue'=>'Pahintulutan at Magpatuloy','verbSkip'=>'Laktawan','Skipping, please wait'=>'Nilalaktawan, mangyaring maghintay','Continue'=>'Magpatuloy','Please wait'=>'Mangyaring maghintay','as activating pluginActivating'=>'I-activate','This will allow %s to'=>'Pahihintulutan nito ang %s na','Privacy Policy'=>'Patakaran sa Pagkapribado','Terms of Service'=>'Mga Tuntunin ng Serbisyo','License Agreement'=>'Kasunduan sa Lisensya','Have a license key?'=>'May susi ng lisensya?','Activate License'=>'I-activate ang Lisensya','View Basic Profile Info'=>'Tingnan ang Pangunahing Impormasyon ng Profile','Your WordPress user\'s: first & last name, and email address'=>'Ang pangalan at apelyido, at email address ng iyong WordPress user','View Basic Website Info'=>'Tingnan ang Pangunahing Impormasyon ng Website','Homepage URL & title, WP & PHP versions, and site language'=>'URL at pamagat ng Homepage, mga bersyon ng WP at PHP, at wika ng site','View Basic %s Info'=>'Tingnan ang Pangunahing Impormasyon ng %s','Current %s & SDK versions, and if active or uninstalled'=>'Kasalukuyang mga bersyon ng %s at SDK, at kung aktibo o naka-uninstall','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Mga update, anunsyo, marketing, walang spam','View Diagnostic Info'=>'Tingnan ang Diagnostic Info','WordPress & PHP versions, site language & title'=>'Mga bersyon ng WordPress at PHP, wika at pamagat ng site','View Plugins & Themes List'=>'Tingnan ang Listahan ng mga Plugin at Tema','Names, slugs, versions, and if active or not'=>'Mga pangalan, slug, bersyon, at kung aktibo o hindi','optional'=>'opsyonal','Never miss an important update'=>'Huwag palampasin ang anumang mahalagang update','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Ipinakilala namin ang opt-in na ito upang hindi mo kailanman mapalampas ang isang mahalagang update at matulungan kaming gawing mas tugma ang %s sa iyong site at mas mahusay sa paggawa ng kung ano ang kailangan mo rito.','Thank you for updating to %1$s v%2$s!'=>'Salamat sa pag-update sa %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Ang unlapi ay dapat na 1 hanggang 8 na maliit na titik o numero, magsimula sa isang titik, at hindi dapat ipangalan sa plugin.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'Ang "%s" ay hindi isang code ng wika. Gumamit ng isang WordPress locale tulad ng fr_FR o de_DE.','List at least one language.'=>'Maglista ng kahit isang wika.','You are not allowed to translate this item.'=>'Hindi ka pinapayagang isalin ang item na ito.','This item already has a version in that language.'=>'Mayroon nang bersyon ang item na ito sa wikang iyon.','That translation engine is not available on this site.'=>'Hindi available sa site na ito ang translation engine na iyon.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Ang magkaibang mga engine sa bawat wika, awtomatikong fallback, at mga spending cap ay mga feature ng Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Ang bawat wika ay dapat na isa sa mga wika ng site, na may available na engine.','The fallback list may only name available engines.'=>'Ang listahan ng fallback ay maaari lamang maglaman ng mga available na engine.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Ang buwanang takip ay isang halaga sa US dollars, zero o higit pa, para sa isang available na engine.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Ang mga ginustong salin at tono sa bawat wika ay mga feature ng Tranzly Pro. Libre ang listahan ng do-not-translate.','Glossary entries must be grouped by one of the site\'s languages.'=>'Ang mga entri sa glossary ay dapat i-grupo sa isa sa mga wika ng site.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Ang tono ay itinatakda sa bawat wika ng site: default sa pormalidad, higit pa o mas mababa, kasama ang mga opsyonal na tagubilin.','The value for %s is not one of the allowed choices.'=>'Ang halaga para sa %s ay hindi isa sa mga pinapayagang pagpipilian.','The background queue is not available on this site.'=>'Hindi available sa site na ito ang background queue.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Ang isang trabaho sa pagsasalin ay tumatakbo bilang ang taong nagsisimula nito, kaya ang isang user ay dapat na nakakonekta.','There is nothing you are allowed to translate in that selection.'=>'Walang anuman na pinahihintulutan kang isalin sa pagpipiliang iyon.','That item is not part of a translation job.'=>'Ang item na iyon ay hindi bahagi ng trabaho sa pagsasalin.','You are not allowed to change that translation.'=>'Hindi ka pinapayagang baguhin ang pagsasalin na iyon.','This item\'s group already has a %1$s version (#%2$d).'=>'Mayroon nang %1$s bersiyon (#%2$d) ang grupo ng item na ito.','An item cannot be its own translation.'=>'Hindi maaaring maging salin ng sarili nito ang isang aytem.','That item is already a translation of something else. Unlink it first.'=>'Ang item na iyon ay isa nang salin ng ibang bagay. I-unlink muna ito.','The translation link could not be saved.'=>'Hindi na-save ang link ng pagsasalin.','That text cannot be translated here.'=>'Hindi maaaring isalin ang tekstong iyon dito.','That media text cannot be translated here.'=>'Hindi maaring isalin dito ang tekstong pang-media na iyon.','A translation can be published or kept as a draft.'=>'Ang isang pagsasalin ay maaaring i-publish o panatilihin bilang isang draft.','You are not allowed to publish this kind of content.'=>'Hindi ka pinahihintulutang mag-publish ng ganitong uri ng nilalaman.','This item is already written in that language.'=>'Nakatala na ang aytem na ito sa wikang iyon.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Ang pagsasalin na ito ay inedit ng isang tao (o na-import), kaya ito ay protektado. I-unlock ito upang isalin itong muli.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Wala pang naka-setup na translation engine. Magdagdag ng key para dito sa Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Hindi pa naka-set up ang translation engine na iyon: idagdag muna ang key nito.','The same text is being translated by another job right now; this item will use that answer.'=>'Isinasalin na rin ang parehong teksto ng isa pang trabaho ngayon; gagamitin ng aytem na ito ang sagot na iyon.','No translation engine could take this item.'=>'Walang makina ng pagsasalin ang nakakuha sa aytem na ito.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Hindi nagbalik ang makina ng pagsasalin para sa bawat bahagi ng aytem na ito. Walang binago.','AI model'=>'Model ng AI','AI model (%1$s %2$s)'=>'Modelo ng AI (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'Kasalukuyang nakakaranas ng mga problema ang %s. Subukang muli mamaya, o gumamit ng ibang engine.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Hindi maabot ng iyong site ang %s. Suriin na maaari itong gumawa ng mga papalabas na koneksyon, pagkatapos ay subukang muli.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'Hindi tinanggap ng %s ang iyong API key. Suriin ang key sa Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Naubos na ang quota o balanse ng iyong %s account. Mag-top up sa kanila, o gumamit ng ibang engine.','%s asked us to slow down. It will be tried again automatically.'=>'Hiniling sa amin ng %s na bagalan ito. Susubukan itong muli nang awtomatiko.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Napakahaba ng tekstong ito para sa %s nang sabay-sabay. Hatiin ang nilalaman, o gumamit ng ibang engine.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'Tinanggihan ng %s na isalin ang nilalamang ito. Subukan ang ibang makina, o isalin ito nang manu-mano.','%s does not translate this language. Choose another engine for it.'=>'Hindi isinasalin ng %s ang wikang ito. Pumili ng ibang engine para rito.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Naabot na ang limitasyon sa paggastos ngayong buwan para sa %s, kaya wala nang iba pang ipinadala rito. Itaas ang limitasyon sa Tranzly → Engines, o maghintay hanggang sa susunod na buwan.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Ang pagsasalin gamit ang %s ay nabigo dahil sa isang dahilan na hindi matukoy ng Tranzly. Ang mga detalye ay nasa ibaba.','An engine id must be lowercase letters, digits and hyphens.'=>'Ang isang engine id ay dapat na mga titik na maliliit (lowercase), numero, at gitling.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Binuo ni Neil Lock, CEO ng Zinn Digital® Ltd','Version %s'=>'Bersyon %s','Tranzly website'=>'Website ng Tranzly','Zinn Digital® website'=>'Website ng Zinn Digital®','Settings saved.'=>'Naka-save na ang mga setting.','See the Pro plans and pricing'=>'Tingnan ang mga Pro plan at pagpepresyo','Languages'=>'Mga Wika','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Ang unang wika ay ang wikang kinasusulatan ng iyong nilalaman. Naglilipat ang mga bisita gamit ang block ng pagpapalit ng wika.','(default)'=>'(default)','Locale code'=>'Code ng lokale','For example fr_FR'=>'Halimbawa, fr_FR','Name (optional)'=>'Pangalan (opsyonal)','For example Français'=>'Halimbawa Français','Add language'=>'Magdagdag ng wika','Front-end output'=>'Output sa front-end','Class name prefix'=>'Prefix ng pangalan ng klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Nagsisimula sa prefix na ito ang bawat pangalan ng klase na ipi-print ng plugin sa iyong mga pahina, kaya hindi nahuhulaan ng mga pahina kung aling plugin ang gumawa sa mga ito. 1 hanggang 8 maliliit na titik o numero, na nagsisimula sa isang titik.','Beta updates'=>'Mga beta update','This site receives beta versions as updates.'=>'Ang site na ito ay tumatanggap ng mga beta version bilang mga update.','This site receives stable versions only.'=>'Ang site na ito ay tumatanggap lamang ng mga matatag na bersyon.','Change this on the Account page'=>'Palitan ito sa pahina ng Account','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Inaalok ang mga bersyong beta sa mga lisensyadong pag-install ng Pro na nakakonekta sa kanilang account. Kapag nakakonekta na, maaari kang sumali mula sa pahina ng Account.','Save settings'=>'I-save ang mga setting','First engine that is set up'=>'Unang makina na naka-set up','Key saved. It is stored encrypted and never shown again.'=>'Nai-save na ang key. Naka-encrypt ito kapag nakaimbak at hindi na kailanman ipapakita muli.','Engine settings saved.'=>'Na-save na ang mga setting ng makina.','Glossary saved.'=>'Na-save ang Glossary.','Your keys'=>'Ang iyong mga susi','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Ang Tranzly ay tumatawag sa mga serbisyo ng pagsasalin gamit ang iyong sariling account. Ang mga susi ay nakaimbak nang naka-encrypt sa iyong database at ipinapadala lamang sa serbisyo kung saan sila nabibilang. Ang mga susi ng modelo ng AI ay itinakda sa mga setting ng AI.','%s API key'=>'%s API key','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Na-save na: %s. Maglagay ng bagong key para palitan ito, o i-save ang isang blangkong field para tanggalin ito.','No key saved.'=>'Walang naka-save na key.','Azure region (leave empty for a global resource)'=>'Rehiyon ng Azure (iwanang blangko para sa isang global na mapagkukunan)','Save key'=>'I-save ang key','Check my DeepL usage'=>'Suriin ang aking paggamit ng DeepL','%1$s of %2$s characters used this billing period.'=>'%1$s sa %2$s na character ang nagamit sa billing period na ito.','Which engine translates'=>'Aling makina ang nagsasalin','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Wala pang nakatakdang engine. Mag-save ng key sa itaas (o mag-set up ng AI model) para simulan ang pagsasalin.','Default engine'=>'Default na engine','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Ang magkaibang engine bawat wika, awtomatikong fallback, and buwanang limitasyon sa paggastos ay mga tampok ng Tranzly Pro.','Engine for %s'=>'Engine para sa %s','The default engine'=>'Ang default na engine','If an engine fails or reaches a limit, try these next, in this order'=>'Kung ang isang engine ay mabigo o umabot sa limitasyon, subukan ang mga sumusunod, sa ganitong pagkakasunud-sunod','Monthly spending caps'=>'Buwanang gastusin sa caps','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Kapag umabot sa limitasyon nito ang isang makina, wala nang ipinapadala rito hanggang sa susunod na buwan at ipinapakita ng ulat ng nabigong pagsasalin ang dahilan. Iwanang bakante kung walang limitasyon.','%1$s (spent this month: $%2$s)'=>'%1$s (nagastos ngayong buwan: $%2$s)','Save caps'=>'I-save ang mga takip','Glossary and words never translated'=>'Glosaryo at mga salitang hindi kailanman isinalin','Never translate these words (one per line)'=>'Huwag kailanman isalin ang mga salitang ito (isa sa bawat linya)','Brand and product names stay exactly as they are, with every engine.'=>'Ang mga pangalan ng brand at produkto ay nananatiling eksakto kung ano sila, sa bawat engine.','Preferred translations and tone per language are Tranzly Pro features.'=>'Ang mga gustong salin at tono para sa bawat wika ay mga feature ng Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Mga ginustong pagsasalin (isa bawat linya: term = translation)','Formality'=>'Pormalidad','Default'=>'Default','Formal'=>'Pormal','Informal'=>'Hindi pormal','Style instructions (audience, brand voice)'=>'Mga tagubilin sa estilo (mga tagapakinig, boses ng brand)','Save glossary'=>'I-save ang glosaryo','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Nagsimula ang trabaho na may %d na isasalin. Tumatakbo ito sa background: maaari mong isara ang pahinang ito.','Queued again.'=>'Naka-queue muli.','Running'=>'Naka-run','Finished'=>'Tapos na','Cancelled'=>'Kanselahin','Translate in the background'=>'Isalin sa background','Set up a translation engine in the Engines tab first.'=>'Mag-set up muna ng translation engine sa Engines tab.','Translate every'=>'Isalin ang bawat isa','Into'=>'Sa loob ng','With'=>'Kasama ang','Each language’s own engine'=>'Sariling makina ng bawat wika','Publish the translations (otherwise they are saved as drafts)'=>'I-publish ang mga isinalin (kung hindi ay mase-save ang mga ito bilang mga draft)','Estimate the cost'=>'Tantihin ang halaga','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d na mga post, %2$s na mga karakter. Ang presyo para sa engine na ito ay hindi alam nang maaga.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d na post, %2$s na character: humigit-kumulang $%3$s sa iyong sariling account.','Start translating'=>'Simulan ang pagsasalin','Jobs'=>'Mga Trabaho','No translation jobs yet.'=>'Wala pang mga trabaho sa pagsasalin.','Job %1$d — %2$s'=>'Trabaho %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d ng %2$d ang naisalin, %3$d ang nabigo, %4$d ang lumaktaw (protektado o nasa wikang iyon na)','Stop this job'=>'Ihinto ang trabahong ito','See what failed and why'=>'Tingnan kung ano ang nabigo at kung bakit','Content'=>'Nilalaman','Language'=>'Wika','What went wrong'=>'Ano ang nagkamali','Fix it'=>'Ayusin ito','Details'=>'Mga Detalye','Retry with'=>'Subukan ulit gamit ang','The same engine'=>'Ang parehong engine','Retry'=>'Subuking muli','Translate by hand'=>'Isalin nang mano-mano','Languages and settings'=>'Mga Wika at mga setting','Engines'=>'Mga Engine','Translation jobs'=>'Mga trabaho sa pagsasalin','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Magdagdag ng pangalawang wika sa ilalim ng Tranzly sa admin menu, at lalabas dito ang switcher.','Switcher'=>'Tagapag-lipat','Accessible label'=>'Madalas na label','block titleLanguage switcher'=>'Tagapaglipat ng Wika','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Mga link sa pahinang ito sa bawat wika ng site. Wala itong ipinapakita hanggang sa dalawa o higit pang wika ang nakalista.','block keywordlanguage'=>'wika','block keywordswitcher'=>'tagapaglipat','block keywordtranslation'=>'pagsasalin']];